flags.typeql:
match
$u isa user, has handle $h, has area $a, has size $s;
let $total = $a + $s;
sort $total desc;
limit 5;
fetch {
  "user": $h,
  "total": $total
};

match
$u isa user, has color "#3CB371";
limit 5;
fetch {
  "handle": $u.handle
};

match
$u1 isa user, has handle "vtcodes.dev";
interacted (source_user: $u1, target_user: $u2);
$u2 has handle $h;
limit 5;
fetch {
  "interactedUser": $h
};
